// Aviso y configuracion de cookies. La unica cookie que no es tecnica es la de
// Google Analytics: aceptar activa solo analytics_storage, nunca las de
// publicidad, que la web no usa. La eleccion se guarda en cookiesAceptadas y se
// puede cambiar cuando se quiera en /politica-cookies.html#configuracion.
//
// Cada eleccion se cuenta, sin saber de quien, en /api/privacidad (ver server.js).
// No lleva «cookies» en la ruta para que los bloqueadores no la corten.

function setCookie(name, value, days) {
    let expires = '';
    if (days) {
        const date = new Date();
        date.setTime(date.getTime() + days * 24 * 60 * 60 * 1000);
        expires = '; expires=' + date.toUTCString();
    }
    document.cookie = name + '=' + (value || '') + expires + '; path=/';
}

function getCookie(name) {
    const nameEQ = name + '=';
    const ca = document.cookie.split(';');
    for (let i = 0; i < ca.length; i++) {
        const c = ca[i].trim();
        if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length);
    }
    return null;
}

function avisarEleccion(e) {
    try { navigator.sendBeacon && navigator.sendBeacon('/api/privacidad?e=' + e); } catch (x) { /* sin beacon */ }
}

// Primera pagina de la visita: sin referer de la propia web. Solo ahi cuenta el
// «mostrado», o quien ignora el aviso y navega contaria una vez por pagina.
function esPrimeraPagina() {
    try { return !document.referrer || new URL(document.referrer).host !== location.host; } catch (x) { return true; }
}

function actualizarConsentimiento(estado) {
    if (typeof gtag === 'function') gtag('consent', 'update', { analytics_storage: estado });
}

// Al retirar el consentimiento hay que borrar las cookies de Analytics que ya
// estaban puestas, no solo dejar de poner nuevas. GA las pone en el dominio sin
// www, asi que se borran en los dos.
function borrarCookiesAnalytics() {
    const host = location.hostname;
    const dominios = ['', host, '.' + host.replace(/^www\./, '')];
    document.cookie.split(';').forEach(function (c) {
        const nombre = c.split('=')[0].trim();
        if (nombre.indexOf('_ga') !== 0) return;
        dominios.forEach(function (d) {
            document.cookie = nombre + '=; Max-Age=0; path=/' + (d ? '; domain=' + d : '');
        });
    });
}

function ocultarAviso() {
    const aviso = document.getElementById('cookieConsent');
    if (aviso) aviso.style.display = 'none';
}

function aceptarCookies() {
    avisarEleccion('aceptar');
    setCookie('cookiesAceptadas', 'true', 365);
    actualizarConsentimiento('granted');
    ocultarAviso();
    pintarEstadoCookies(true);
}

function rechazarCookies() {
    avisarEleccion('rechazar');
    setCookie('cookiesAceptadas', 'false', 365);
    actualizarConsentimiento('denied');
    borrarCookiesAnalytics();
    ocultarAviso();
    pintarEstadoCookies(true);
}

function configurarCookies() {
    window.location.href = '/politica-cookies.html#configuracion';
}

// Panel de /politica-cookies.html#configuracion: dice que hay elegido ahora.
function pintarEstadoCookies(recienCambiado) {
    const estado = document.getElementById('estado-cookies');
    if (!estado) return;
    const valor = getCookie('cookiesAceptadas');
    const texto = valor === 'true'
        ? 'Ahora mismo las cookies de análisis están <strong>activadas</strong>.'
        : valor === 'false'
            ? 'Ahora mismo las cookies de análisis están <strong>desactivadas</strong>.'
            : 'Todavía no has elegido: las cookies de análisis están <strong>desactivadas</strong> hasta que las aceptes.';
    estado.innerHTML = texto + (recienCambiado ? ' Tu elección se ha guardado.' : '');
}

document.addEventListener('DOMContentLoaded', function () {
    const aviso = document.getElementById('cookieConsent');
    if (aviso && !getCookie('cookiesAceptadas')) {
        aviso.style.display = 'block';
        if (esPrimeraPagina()) avisarEleccion('mostrado');
    }
    pintarEstadoCookies(false);
});
